import cProfile
import pstats


def count_calls(func, *args):
    profiler = cProfile.Profile()
    result = profiler.runcall(func, *args)
    profile = pstats.Stats(profiler).get_stats_profile()
    calls = {}
    for name, info in profile.func_profiles.items():
        if info.file_name != "~":
            calls[name] = int(info.ncalls.split("/")[0])
    return result, calls

