import sqlite3


def load_orders(orders):
    db = sqlite3.connect(":memory:")
    db.execute("CREATE TABLE orders (customer TEXT, amount REAL)")
    with db:
        db.executemany("INSERT INTO orders VALUES (?, ?)", orders)
    return db


def totals(db):
    rows = db.execute(
        "SELECT customer, SUM(amount) AS total FROM orders"
        " GROUP BY customer ORDER BY total DESC, customer"
    )
    return rows.fetchall()

